                ['id' => $id ?? 0, 'status' => Orcamento::STATUS_RASCUNHO],
                $dados
            ));
            $itensDraft = array_map(
                fn(array $raw) => OrcamentoItem::fromArray(array_merge(
                    ['id' => 0, 'orcamento_id' => $id ?? 0, 'subtotal' => 0],
                    $raw
                )),
                $itensRaw
            );

            $this->view('orcamentos/form', [
                'page_title' => $id ? 'Editar Orçamento' : 'Novo Orçamento',
                'orcamento' => $orcamentoDraft,
                'itens' => $itensDraft,
                'clientes' => $this->service->listarClientes(),
                'produtos' => $this->service->listarProdutos(),
                'servicosCatalogo' => $this->service->listarServicosCatalogo(),
                'editando' => (bool) $id,
            ]);
            return;
        }

        $msg = $id ? 'Orçamento atualizado com sucesso!' : 'Orçamento criado com sucesso!';

        $this->audit->registrar(
            'orcamentos',
            $id ? 'ATUALIZAR' : 'CRIAR',
            'orcamento',
            (int)($resultado['id'] ?? $id ?? 0),
            $msg,
            [
                'cliente_id' => $dados['cliente_id'] ?? null,
                'itens' => count((array) $itensRaw),
            ]
        );

        $this->flash('success', $msg);
        $this->redirecionar();
    }

    /**
 * Controller: OrcamentoController
 *
 * Responsabilidades exclusivas:
 *  - Verificar autenticaÃ§Ã£o e autorizaÃ§Ã£o do usuÃ¡rio
