    private function visualizar(int $id): void
    {
        $resultado = $this->service->buscarParaEdicao($id);

        if ($resultado === null) {
            $this->flash('error', 'Orçamento nÃ£o encontrado.');
            $this->redirecionar();
        }

        $this->view('orcamentos/visualizar', [
            'page_title' => 'Orçamento ' . ($resultado['orcamento']->codigo ?? "#{$id}"),
            'orcamento' => $resultado['orcamento'],
            'itens' => $resultado['itens'],
            'servico' => (new ServicoRepository($this->pdo))->findByOrcamentoId($id),
        ]);
    }

    private function pdf(int $id): void
    {
        $resultado = $this->service->buscarParaEdicao($id);

        if ($resultado === null) {
            $this->flash('error', 'Orçamento nÃ£o encontrado.');
            $this->redirecionar();
        }

        $orcamento = $resultado['orcamento'];
        $itens = $resultado['itens'];

        $logoHtml = '';
        $helperPath = __DIR__ . '/../../../public/admin/financeiro/relatorio_helper.php';
        if (file_exists($helperPath)) {
            require_once $helperPath;
            if (function_exists('getLogoHtml')) {
                $logoHtml = getLogoHtml('logo');
            }
        }

        ob_start();
        require __DIR__ . '/../../views/orcamentos/pdf.php';
        $html = ob_get_clean();

        $options = new Options();
        $options->set('defaultFont', 'Arial');
        $options->set('isRemoteEnabled', true);
        $options->set('isHtml5ParserEnabled', true);

        $dompdf = new Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();

        $codigo = $orcamento->codigo ?? ('ORC-' . $orcamento->id);
        $filename = 'orcamento_' . preg_replace('/[^A-Za-z0-9\-_]/', '_', $codigo) . '.pdf';

        header('Content-Type: application/pdf');
        header('Content-Disposition: inline; filename="' . $filename . '"');
        header('Cache-Control: max-age=0');

        echo $dompdf->output();
        exit();
    }

    private function cancelar(int $id): void
    {
        $res = $this->service->cancelar($id);

        if ($res['ok']) {
            $this->audit->registrar('orcamentos', 'CANCELAR', 'orcamento', $id, 'Orçamento cancelado.');
        }

        $res['ok']
            ? $this->flash('success', 'Orçamento cancelado.')
            : $this->flash('error', implode('<br>', $res['erros']));

        $this->redirecionar();
    }

    private function estornar(int $id): void
    {
        $res = $this->service->estornarAprovacao($id, (int)($_SESSION['user_id'] ?? 0));

        if ($res['ok']) {
            $this->audit->registrar('orcamentos', 'ESTORNAR', 'orcamento', $id, 'Orçamento estornado e reaberto.');
        }

        $res['ok']
            ? $this->flash('success', 'Orçamento estornado e reaberto com sucesso.')
            : $this->flash('error', implode('<br>', $res['erros']));

        $this->redirecionar();
    }

    private function excluir(int $id): void
    {
        $res = $this->service->excluir($id);

        if ($res['ok']) {
            $this->audit->registrar('orcamentos', 'EXCLUIR', 'orcamento', $id, 'Orçamento excluÃ­do.');
        }

        $res['ok']
            ? $this->flash('success', 'Orçamento excluído com sucesso.')
            : $this->flash('error', implode('<br>', $res['erros']));

        $this->redirecionar();
    }

